import { camera, createAuraApp, group, looks, material, primitives, scene } from "@aura3d/engine";

// Walking-in-place spider built only from primitives. Every leg is a chain of joint groups:
// yaw (about Y, points the leg at its foot) -> femur (about Z) -> tibia (about Z).
// Foot targets are generated by a looping gait; a two-bone IK solve turns them into joint angles.

const PERIOD = 2; // seconds per full gait cycle (seamless loop)
const BODY_Y = 0.95; // resting height of the body centre
const BOB = 0.04;
const L1 = 0.95; // femur length
const L2 = 1.35; // tibia length
const STRIDE = 0.28; // half stride along z
const LIFT = 0.42; // foot lift height

const shell = material.pbr({ color: "#3a2430", roughness: 0.45, metallic: 0.1 });
const marking = material.pbr({ color: "#d9692b", roughness: 0.5 });
const legMat = material.pbr({ color: "#2b1b24", roughness: 0.5, metallic: 0.1 });
const jointMat = material.pbr({ color: "#e0a24a", roughness: 0.4 });
const eyeMat = material.pbr({ color: "#0b0b0e", roughness: 0.15, metallic: 0.3 });

const hipZ = [0.32, 0.12, -0.1, -0.3];
const footZ = [1.05, 0.5, -0.2, -0.85];
const footX = [1.3, 1.55, 1.55, 1.35];
const HIP_X = 0.4;

const segment = (name: string, length: number, radius: number) =>
  primitives.capsule({ name, size: [radius * 2, length, radius * 2], material: legMat }).position(0, -length / 2, 0);

const legNode = (id: string, x: number, z: number) =>
  group(`${id}-yaw`, [
    primitives.sphere({ name: `${id}-hip-ball`, size: 0.24, material: jointMat }),
    group(`${id}-fem`, [
      segment(`${id}-femur`, L1, 0.075),
      group(`${id}-tib`, [
        primitives.sphere({ name: `${id}-knee-ball`, size: 0.2, material: jointMat }),
        segment(`${id}-tibia`, L2, 0.055),
        primitives.sphere({ name: `${id}-foot`, size: 0.1, material: legMat }).position(0, -L2, 0)
      ], { position: [0, -L1, 0] }).runtime({ id: `${id}-tib`, mutable: true })
    ]).runtime({ id: `${id}-fem`, mutable: true })
  ], { position: [x, 0, z] }).runtime({ id: `${id}-yaw`, mutable: true });

const legs = [] as ReturnType<typeof legNode>[];
for (const [sideName, sx] of [["l", -1], ["r", 1]] as const) {
  for (let i = 0; i < 4; i += 1) legs.push(legNode(`${sideName}${i}`, sx * HIP_X, hipZ[i]!));
}

const eyes = [
  [-0.12, 0.2, 0.46, 0.13], [0.12, 0.2, 0.46, 0.13],
  [-0.26, 0.14, 0.4, 0.09], [0.26, 0.14, 0.4, 0.09]
] as const;

const spider = group("spider", [
  primitives.sphere({ name: "thorax", size: [0.95, 0.6, 1.05], material: shell }).position(0, 0, 0.18),
  primitives.sphere({ name: "head", size: [0.6, 0.45, 0.45], material: shell }).position(0, 0.02, 0.62),
  primitives.sphere({ name: "abdomen", size: [1.1, 0.95, 1.4], material: shell }).position(0, 0.12, -0.8),
  primitives.sphere({ name: "mark-a", size: [0.5, 0.12, 0.45], material: marking }).position(0, 0.58, -0.78),
  primitives.sphere({ name: "mark-b", size: [0.3, 0.1, 0.3], material: marking }).position(0, 0.5, -1.25),
  ...eyes.map(([x, y, z, s], i) => primitives.sphere({ name: `eye${i}`, size: s, material: eyeMat }).position(x, y, z)),
  primitives.cone({ name: "fang-l", size: [0.07, 0.2, 0.07], material: jointMat }).position(-0.12, -0.12, 0.82),
  primitives.cone({ name: "fang-r", size: [0.07, 0.2, 0.07], material: jointMat }).position(0.12, -0.12, 0.82),
  ...legs
], { position: [0, BODY_Y, 0] }).runtime({ id: "spider", mutable: true });

const app = createAuraApp("#app", {
  scene: scene()
    .add(looks.preset("product-studio", { exposureEv: -0.8 }))
    .add(primitives.plane({ name: "floor", size: [16, 1, 16], material: material.pbr({ color: "#d4d6db", roughness: 0.9 }) }))
    .add(spider)
    .camera(camera.perspective({ position: [4.1, 3.3, 5.1], target: [0, 0.6, 0], fov: 40 })),
  ...looks.appOptions("product-studio")
});

const smooth = (x: number) => x * x * (3 - 2 * x);

function poseLegs(time: number): void {
  const u = (time / PERIOD) % 1;
  const bob = BOB * Math.sin(u * Math.PI * 4 + Math.PI / 2 * 0); // two steps per cycle
  const bodyY = BODY_Y + bob;
  app.nodes.require("spider").setPosition(0, bodyY, 0);
  app.nodes.require("spider").setRotation(0.012 * Math.sin(u * Math.PI * 2), 0.03 * Math.sin(u * Math.PI * 2), 0.015 * Math.cos(u * Math.PI * 2));

  for (let side = 0; side < 2; side += 1) {
    const sx = side === 0 ? -1 : 1;
    const sideName = side === 0 ? "l" : "r";
    for (let i = 0; i < 4; i += 1) {
      // Diagonal pairs: (l0, r1, l2, r3) vs (r0, l1, r2, l3), half a cycle apart.
      const diagonal = (side + i) % 2;
      const v = (u + diagonal * 0.5) % 1;
      let s: number;
      let lift = 0;
      if (v < 0.5) {
        const w = v / 0.5;
        s = -STRIDE + 2 * STRIDE * smooth(w);
        lift = LIFT * Math.sin(Math.PI * w);
      } else {
        const w = (v - 0.5) / 0.5;
        s = STRIDE - 2 * STRIDE * w;
      }
      // Foot target relative to the hip, in body space (body bobs, feet stay on the floor).
      const dx = sx * footX[i]! - sx * HIP_X;
      const dz = footZ[i]! + s - hipZ[i]!;
      const dy = -bodyY + 0.05 + lift;
      const d = Math.hypot(dx, dz);
      let D = Math.hypot(d, dy);
      D = Math.min(D, L1 + L2 - 0.02);
      const beta = Math.atan2(dy, d);
      const A = Math.acos(Math.max(-1, Math.min(1, (L1 * L1 + D * D - L2 * L2) / (2 * L1 * D))));
      const psi1 = beta + A; // femur elevation above the horizontal
      const kx = L1 * Math.cos(psi1);
      const ky = L1 * Math.sin(psi1);
      const psi2 = Math.atan2(D * Math.sin(beta) - ky, D * Math.cos(beta) - kx);
      const id = `${sideName}${i}`;
      app.nodes.require(`${id}-yaw`).setRotation(0, Math.atan2(-dz, dx), 0);
      app.nodes.require(`${id}-fem`).setRotation(0, 0, Math.PI / 2 + psi1);
      app.nodes.require(`${id}-tib`).setRotation(0, 0, psi2 - psi1);
    }
  }
}

app.onFrame((f) => poseLegs(f.time));
void app.ready().then(() => {
  poseLegs(0);
  requestAnimationFrame(() => requestAnimationFrame(() => { (window as unknown as { __EVAL_READY__?: boolean }).__EVAL_READY__ = true; }));
});
